846	    name_index = index["name"]
847	    date_index = index.get("important_date")
848	
849	    existing = {}
850	    for cid, cname in database.execute("SELECT id, name FROM clients"):
851	        existing[(cname or "").strip().casefold()] = cid
852	
853	    imported = []
854	    failures = []
855	    seen_in_file = {}
856	
857	    for row_number, raw in enumerate(data_rows, start=1):
