920	def main():
921	    parser = argparse.ArgumentParser(description="ClientBook - 客户联系人与商机记录")
922	    commands = parser.add_subparsers(dest="command", required=True)
923	    serve = commands.add_parser("serve", help="Start the HTTP service")
924	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
925	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
